-- Resources content for the simplified program page in Log (CLAUDE.md,
-- "Resources stay in step with the code"): one Edit per schedule, the This
-- week strip removed, program details (now including the NPR collection and
-- feed hour) edited in place. Content only — no schema.

select private.rc_release_guide(
  p_slug => 'log-schedule-a-program',
  p_tool_key => 'log',
  p_title => 'Schedule a program',
  p_summary => 'See the week, change when a program airs, edit a program''s details, and find programs that still need a clock.',
  p_screen_keys => array['log.program', 'log.program.schedule'],
  p_sort_order => 20,
  p_version_note => 'Updated for in-place program details and the NPR connection',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Programs is where the schedule and every clock are reached from. Scheduling and changing a clock are producer tasks."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"See the schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Week","marks":[{"type":"bold"}]},{"type":"text","text":" view shows the week as a grid, one column per day, with each program at its air time and the clock it runs on. Programs still on the shared placeholder clock are shaded amber. Select a block to see its details, then "},{"type":"text","text":"Edit schedule","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Open program","marks":[{"type":"bold"}]},{"type":"text","text":". Use Prev, Next, and Today to change the week. The "},{"type":"text","text":"List","marks":[{"type":"bold"}]},{"type":"text","text":" view shows the same programs as a table."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find what needs attention"}]},{"type":"paragraph","content":[{"type":"text","text":"In the list, "},{"type":"text","text":"Needs a clock","marks":[{"type":"bold"}]},{"type":"text","text":" shows the programs still on the placeholder clock, and "},{"type":"text","text":"Not scheduled","marks":[{"type":"bold"}]},{"type":"text","text":" shows programs with no current schedule. Clocks no program uses are listed under "},{"type":"text","text":"Unused clocks","marks":[{"type":"bold"}]},{"type":"text","text":" below the list."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Change when a program airs"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open the program. Under "},{"type":"text","text":"When it airs","marks":[{"type":"bold"}]},{"type":"text","text":" each schedule shows its days and time; select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":". The clock it runs on is changed in the same editor."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose the days, the start time, and the length. The quick buttons set weekdays, the weekend, or every day."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set when the schedule starts and, if it stops, when it ends. Pick the clock it runs on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check the preview on the right. It shows the times, the next airing, and whether another program airs at the same time on those days. An overlap is a warning; it doesn't stop you saving."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Save schedule","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Rundowns that were already generated keep the clock they were built from; a new clock applies to rundowns generated from then on."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"+ Add a time","marks":[{"type":"bold"}]},{"type":"text","text":" on a program's page, choose its days, time, and clock, and save. If the clock doesn't exist yet, select "},{"type":"text","text":"Create a clock for this program","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a program's details"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Details","marks":[{"type":"bold"}]},{"type":"text","text":" panel on a program's page holds its name, kind, description, and NPR connection. Producers select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" on the panel to change them in place, then "},{"type":"text","text":"Save changes","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Collection ID","marks":[{"type":"bold"}]},{"type":"text","text":" is NPR's ID for the program. With it set, Log reads that day's NPR stories for the program's rundowns. Leave it blank to stop reading NPR for the program."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Feed's first hour (Eastern)","marks":[{"type":"bold"}]},{"type":"text","text":" only matters for NPR's multi-hour shows, whose hours alternate on the feed. It lines up NPR's hours with ours so estimated story times are right. Leave it on "},{"type":"text","text":"Same as our schedule","marks":[{"type":"bold"}]},{"type":"text","text":" unless NPR's first hour differs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changing the collection ID clears the program's saved NPR stories from today on, so the next look fetches the new ones. Earlier dates keep what they had."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-09-29-log-program-page-simplified',
  p_tool_key => 'log',
  p_released_on => '2026-09-29',
  p_title => 'A simpler program page, and NPR settings you can edit',
  p_guide_slugs => array['log-schedule-a-program'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A program's page is simpler. Each schedule has one "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" button, which also changes the clock, and the separate This week strip is gone; the full week is one link away. A one-time change or holiday now shows its dates instead of every day of the week. The program's details are edited in place from the "},{"type":"text","text":"Details","marks":[{"type":"bold"}]},{"type":"text","text":" panel, and producers can now set a program's NPR collection ID and feed hour there."}]}]}$body$
);
